var a=[{title:`Voordelen en grenzen`,text:`Werken met lichaamsgewicht kan overal, kost vaak weinig en heeft veel opties voor beginners. Het kan balans, coördinatie, kracht en spieruithouding trainen. Sommige patronen zijn zonder uitrusting of een betrouwbaar ankerpunt moeilijker nauwkeurig zwaarder te maken, vooral hinges voor het onderlichaam die je steeds zwaarder wilt maken en horizontaal trekken.`},{title:`Maak het uitdagend`,text:`Een wall push-up kan leiden naar een incline push-up en daarna een push-up op de vloer. Squats kunnen opbouwen via meer controle, pauzes en later varianten die op één been gericht zijn. Planken kunnen zwaarder worden met een langere hefboom voordat je tijd toevoegt. Maak een oefening alleen zwaarder zolang je je herhalingen nog schoon kunt herhalen. Tientallen makkelijke herhalingen opstapelen kan het trainingseffect richting uithouding verschuiven.`},{title:`Werk met je uitrusting`,text:`Met een veilige optrekstang kun je verticaal trekken trainen, en met een stevig geïnstalleerde suspension trainer kun je mogelijk rows doen. Ga er niet van uit dat een huishoudelijke tafel, deur of reling je lichaamsgewicht kan dragen. Heb je geen veilig anker, kies dan een ander patroon of gebruik de banden en dumbbells die je hebt.`},{title:`Voorbeeld`,text:`Een eerste training kan bestaan uit twee sets van elk: chair squats, incline push-ups, ondersteunde reverse lunges, glute bridges en dead bugs. Kies het aantal herhalingen op basis van hoe goed je de beweging beheerst en hoe zwaar het voelt. Er is geen enkel verplicht doel. Rust lang genoeg om je vorm te behouden.`},{title:`TrainUp gebruiken`,text:`Heb je geen uitrusting, geef dat dan aan in Profiel en stel je vloeroppervlak in en of springen mag. Het schema kiest dan alleen oefeningen met lichaamsgewicht die passen bij je ruimte, sprongbeperking en niveau. Markeer een optrekstang alleen als beschikbaar als die veilig is geïnstalleerd; anders laat het schema oefeningen weg die hem nodig hebben.`}];var t=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NHS: richtlijn voor kracht en soepelheid`,url:`https://www.nhs.uk/live-well/exercise/how-to-improve-strength-flexibility/`},{label:`ACE-oefeningenbibliotheek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var i={sections:a,sources:t};export{i as default,a as sections,t as sources};